# Cards are ints 0..51: rank = c % 13 (0 = deuce ... 12 = ace), suit = c // 13.

_B5 = 13 ** 5


def _straight_top(mask):
    """mask: 13-bit rank mask. Returns top rank index of best straight, or -1."""
    m = (mask << 1) | (mask >> 12)  # bit0 = ace-low, bit(r+1) = rank r
    w = m & (m >> 1) & (m >> 2) & (m >> 3) & (m >> 4)
    if not w:
        return -1
    return w.bit_length() - 1 + 3  # lowest-card bit h of highest window -> top rank h+3


def _pack(cat, ranks):
    v = 0
    for i in range(5):
        v = v * 13 + (ranks[i] if i < len(ranks) else 0)
    return cat * _B5 + v


def score(cards):
    """Score any number (>=1) of cards; best 5-card hand. Higher is better."""
    rc = [0] * 13
    sm = [0, 0, 0, 0]
    for c in cards:
        r = c % 13
        rc[r] += 1
        sm[c // 13] |= 1 << r
    allmask = sm[0] | sm[1] | sm[2] | sm[3]

    flush_mask = 0
    for s in range(4):
        if bin(sm[s]).count("1") >= 5:
            flush_mask = sm[s]
            break
    if flush_mask:
        t = _straight_top(flush_mask)
        if t >= 0:
            return _pack(8, [t])

    quads, trips, pairs, singles = [], [], [], []
    for r in range(12, -1, -1):
        n = rc[r]
        if n == 4:
            quads.append(r)
        elif n == 3:
            trips.append(r)
        elif n == 2:
            pairs.append(r)
        elif n == 1:
            singles.append(r)

    if quads:
        kick = [max(trips + pairs + singles)] if (trips or pairs or singles) else []
        return _pack(7, [quads[0]] + kick)
    if trips and (len(trips) > 1 or pairs):
        second = trips[1] if len(trips) > 1 else pairs[0]
        if len(trips) > 1 and pairs:
            second = max(trips[1], pairs[0])
        return _pack(6, [trips[0], second])
    if flush_mask:
        top5 = [r for r in range(12, -1, -1) if flush_mask >> r & 1][:5]
        return _pack(5, top5)
    t = _straight_top(allmask)
    if t >= 0:
        return _pack(4, [t])
    if trips:
        return _pack(3, [trips[0]] + singles[:2] + pairs[:2])
    if len(pairs) >= 2:
        rest = sorted(pairs[2:] + singles, reverse=True)[:1]
        return _pack(2, [pairs[0], pairs[1]] + rest)
    if pairs:
        return _pack(1, [pairs[0]] + singles[:3])
    return _pack(0, singles[:5])


def featurize(hole, board, n_opp):
    """hole: 2 card ints, board: 0..5 card ints, n_opp: opponents still in (1..7)."""
    r1, r2 = hole[0] % 13, hole[1] % 13
    hi, lo = max(r1, r2), min(r1, r2)
    suited = 1.0 if hole[0] // 13 == hole[1] // 13 else 0.0
    nb = len(board)

    f = [hi / 12.0, lo / 12.0, suited, 1.0 if hi == lo else 0.0, (hi - lo) / 12.0,
         (min(max(n_opp, 1), 7) - 1) / 6.0]
    f += [1.0 if nb == k else 0.0 for k in (0, 3, 4, 5)]

    allc = list(hole) + list(board)
    sc = score(allc)
    cat = sc // _B5
    f += [1.0 if cat == k else 0.0 for k in range(9)]
    f.append(((sc // 13 ** 4) % 13) / 12.0)   # primary rank (e.g. pair rank)
    f.append(((sc // 13 ** 3) % 13) / 12.0)   # secondary rank

    brank = [c % 13 for c in board]
    bmax = max(brank) if brank else -1
    f.append(sum(1 for r in (r1, r2) if r > bmax) / 2.0 if brank else 0.0)  # overcards
    f.append(1.0 if brank and len(set(brank)) < len(brank) else 0.0)         # paired board
    bs = [0, 0, 0, 0]
    for c in board:
        bs[c // 13] += 1
    f.append(max(bs) / 5.0)                                                  # board suitedness
    hs = [0, 0, 0, 0]
    for c in allc:
        hs[c // 13] += 1
    f.append(1.0 if (nb in (3, 4) and max(hs) == 4) else 0.0)                # flush draw
    mask = 0
    for c in allc:
        mask |= 1 << (c % 13)
    m = (mask << 1) | (mask >> 12)
    wins = sum(1 for s in range(9) if bin((m >> s) & 31).count("1") >= 4)
    f.append(min(wins, 2) / 2.0 if nb in (3, 4) else 0.0)                    # straight draw
    f.append(bmax / 12.0 if brank else 0.0)                                  # board high card
    f.append(sum(1 for r in (r1, r2) if r in brank) / 2.0)                   # hole cards pairing board
    f.append(sc / (9.0 * _B5))                                               # overall strength
    return f


def forward(weights, x):
    """Tiny MLP: ReLU hidden layers, sigmoid output. weights = [(W, b), ...], W[j][i]."""
    import math
    a = x
    for li, (W, b) in enumerate(weights):
        out = []
        for j in range(len(b)):
            row = W[j]
            s = b[j]
            for i in range(len(a)):
                s += row[i] * a[i]
            out.append(s)
        if li < len(weights) - 1:
            a = [v if v > 0.0 else 0.0 for v in out]
        else:
            z = out[0]
            z = max(-30.0, min(30.0, z))
            return 1.0 / (1.0 + math.exp(-z))
# ---- END CORE ----


