# ---------------------------------------------------------------- policy knobs
BET_EDGE = 0.20        # bet/open when equity exceeds fair share (1/(n+1)) by this much
RAISE_EDGE = 0.30      # re-raise when facing a bet and edge exceeds this
CALL_MARGIN = 0.03     # extra equity over pot odds required to call
SHOVE_PENALTY = 0.12   # extra required equity when the call is a large part of our stack
BET_FRACTION = 0.6     # bet size as a fraction of the pot
DEBUG = bool(os.environ.get("POKER_DEBUG"))

# ---------------------------------------------------------------- state adapter
# These helpers read the game state defensively (several attribute spellings are
# tried). If POKER_DEBUG=1 is set, parsed values are printed so you can verify them.

def _get(obj, names, default=None):
    for n in names:
        if hasattr(obj, n):
            try:
                v = getattr(obj, n)
                return v() if callable(v) else v
            except Exception:
                continue
    return default


_RANK_WORDS = {"TWO": 0, "THREE": 1, "FOUR": 2, "FIVE": 3, "SIX": 4, "SEVEN": 5, "EIGHT": 6,
               "NINE": 7, "TEN": 8, "JACK": 9, "QUEEN": 10, "KING": 11, "ACE": 12}
_RANK_CHARS = "23456789TJQKA"
_SUIT_CHARS = {"C": 0, "D": 1, "H": 2, "S": 3, "♣": 0, "♦": 1, "♥": 2, "♠": 3}
_SUIT_WORDS = {"CLUBS": 0, "DIAMONDS": 1, "HEARTS": 2, "SPADES": 3}
_saw_zero_rank = [False]


def _unwrap(x):
    # Enum -> its value (if int/str) else its name
    if hasattr(x, "value") and hasattr(x, "name"):
        v = x.value
        return v if isinstance(v, (int, str)) else x.name
    return x


def _rank_index(r):
    r = _unwrap(r)
    if isinstance(r, str):
        t = r.strip().upper()
        if t in _RANK_WORDS:
            return _RANK_WORDS[t]
        if t == "10":
            return 8
        if len(t) == 1 and t in _RANK_CHARS:
            return _RANK_CHARS.index(t)
        if t.isdigit():
            r = int(t)
        else:
            raise ValueError("bad rank %r" % (r,))
    r = int(r)
    if r == 0:
        _saw_zero_rank[0] = True
    if _saw_zero_rank[0] and r <= 12:
        return r            # 0..12 numbering (0 = deuce)
    if r == 1:
        return 12           # 1..13 numbering with ace = 1
    return r - 2            # 2..14 numbering


def _suit_index(s):
    s = _unwrap(s)
    if isinstance(s, str):
        t = s.strip().upper()
        if t in _SUIT_WORDS:
            return _SUIT_WORDS[t]
        if t[:1] in _SUIT_CHARS:
            return _SUIT_CHARS[t[:1]]
        raise ValueError("bad suit %r" % (s,))
    return int(s) % 4


def _card_int(card):
    if isinstance(card, int):
        return card
    if isinstance(card, str):
        t = card.strip()
        return _suit_index(t[-1]) * 13 + _rank_index(t[:-1])
    if isinstance(card, (tuple, list)) and len(card) == 2:
        a, b = card
        try:
            return _suit_index(b) * 13 + _rank_index(a)
        except Exception:
            return _suit_index(a) * 13 + _rank_index(b)
    r = _get(card, ("rank", "value", "number", "face"))
    s = _get(card, ("suit", "colour", "color"))
    if r is None or s is None:
        raise ValueError("cannot parse card %r" % (card,))
    return _suit_index(s) * 13 + _rank_index(r)


def _cards(seq):
    return [_card_int(c) for c in (seq or [])]


def _hole(state):
    me = state.my_player
    seq = _get(me, ("hole_cards", "hand", "cards", "hole", "holecards", "private_cards"))
    if seq is None:
        seq = _get(state, ("hole_cards", "my_cards", "hand", "cards"))
    return _cards(seq)


def _board(state):
    seq = _get(state, ("community_cards", "board", "community", "table_cards", "shared_cards"))
    return _cards(seq)


def _is_live(p):
    # True if the player is still contesting the hand.
    for n in ("folded", "is_folded", "has_folded", "out", "is_out", "eliminated", "busted"):
        if _get(p, (n,), False):
            return False
    for n in ("active", "is_active", "in_hand", "in_game"):
        v = _get(p, (n,), None)
        if v is not None and not v:
            return False
    return True


def _stack(p):
    v = _get(p, ("chips", "stack", "chip_count", "money", "balance"))
    return v if isinstance(v, (int, float)) else None


def _pot(state):
    tot = 0
    for p in state.players:
        v = _get(p, ("chips_in_pot",), None)
        if isinstance(v, (int, float)):
            tot += v
    if tot:
        return tot
    v = _get(state, ("pot", "chips_in_pot", "total_pot"))
    return v if isinstance(v, (int, float)) else 0


# ---------------------------------------------------------------- policy
def _decide(state):
    me = state.my_player
    hole, board = _hole(state), _board(state)
    if len(hole) != 2 or len(board) > 5:
        raise ValueError("unexpected cards hole=%r board=%r" % (hole, board))

    live_others = [p for p in state.players if p is not me and _is_live(p)]
    n_opp = max(1, min(7, len(live_others)))

    equity = forward(WEIGHTS, featurize(hole, board, n_opp))
    fair = 1.0 / (n_opp + 1)
    edge = equity - fair

    max_bet = max(p.chips_bet for p in state.players)
    to_call = max(0, max_bet - me.chips_bet)
    pot = _pot(state)
    bb = _get(state, ("big_blind",), 20) or 20
    stack = _stack(me)

    if DEBUG:
        print("[myAI] hole=%s board=%s n_opp=%d eq=%.3f to_call=%s pot=%s stack=%s"
              % (hole, board, n_opp, equity, to_call, pot, stack))

    def raise_to_size(frac):
        amt = int(max(2 * bb, frac * (pot + to_call)))
        return Action.raise_by(amt)

    if to_call <= 0:
        if edge > BET_EDGE and random.random() < 0.9:
            return raise_to_size(BET_FRACTION + min(0.4, edge - BET_EDGE))
        return Action.check()

    pot_odds = to_call / float(pot + to_call) if (pot + to_call) > 0 else 1.0
    need = pot_odds + CALL_MARGIN
    if stack:
        need += SHOVE_PENALTY * min(1.0, to_call / float(stack))
    if edge > RAISE_EDGE and random.random() < 0.8:
        return raise_to_size(BET_FRACTION)
    if equity > need:
        return Action.call()
    return Action.fold()


def myAI(state: GameState) -> Action:
    try:
        return _decide(state)
    except Exception:
        if DEBUG:
            traceback.print_exc()
        return defaultAI(state)


def defaultAI(state: GameState) -> Action:  # runs if myAI raises, returns an invalid action or takes too long
    return Action.check() if state.my_player.chips_bet == max(player.chips_bet for player in state.players) else Action.fold()
